/** Canonical GM-facing Frame Conn // Mission panel embedded in Foundry's Combat Tracker. */

import { defineFrameConnFeature } from "../../scripts/feature-contract.js";
import { buildDmSitrepViewModel } from "./components/dm-sitrep-view-model.js";
import { renderDmSitrepApplication } from "./components/dm-sitrep-presentation.js";
import { activateDmSitrepListeners } from "./components/dm-sitrep-listeners.js";

const runtime = { sitrepsApi: null, foundryApi: null };
let combatTrackerRoot = null;
let embeddedPanelVisible = false;

function configureRuntime({ sitrepsApi, foundryApi } = {}) {
  if (sitrepsApi !== undefined) runtime.sitrepsApi = sitrepsApi;
  if (foundryApi !== undefined) runtime.foundryApi = foundryApi;
  return runtimeBindings();
}

function runtimeBindings() {
  return Object.freeze({ sitreps: Boolean(runtime.sitrepsApi), foundry: Boolean(runtime.foundryApi) });
}

function assertRuntime() {
  if (!runtime.sitrepsApi || !runtime.foundryApi) {
    throw new Error("Frame Conn DM panel runtime has not been configured.");
  }
}

function normalizeCombatTrackerRoot(html) {
  return html?.[0] ?? html ?? null;
}

const embeddedPanelController = {
  showSetup: false,

  get element() {
    const panel = combatTrackerRoot?.querySelector?.(".lancer-frame-conn-dm-embedded") ?? null;
    return panel ? [panel] : [];
  },

  async render() {
    if (!combatTrackerRoot || !embeddedPanelVisible) return null;
    return renderEmbeddedMissionPanel(combatTrackerRoot);
  }
};

function findEmbeddedPanelHost(root) {
  return root?.querySelector?.(".combat-tracker") ?? root;
}

async function renderEmbeddedMissionPanel(root = combatTrackerRoot) {
  assertRuntime();
  if (!root?.querySelector) return null;

  combatTrackerRoot = root;

  root.querySelector(".lancer-frame-conn-dm-embedded")?.remove();
  if (!embeddedPanelVisible) return null;

  const model = await buildDmSitrepViewModel({
    sitrepsApi: runtime.sitrepsApi,
    foundryApi: runtime.foundryApi
  });

  if (!model.configured) embeddedPanelController.showSetup = true;

  const panel = document.createElement("section");
  panel.className = "lancer-frame-conn-dm-embedded";
  panel.dataset.frameConnSitrepPanel = "true";
  panel.innerHTML = renderDmSitrepApplication(model, {
    showSetup: embeddedPanelController.showSetup
  });

  const host = findEmbeddedPanelHost(root);
  host?.appendChild(panel);

  activateDmSitrepListeners(embeddedPanelController, panel, {
    sitrepsApi: runtime.sitrepsApi,
    foundryApi: runtime.foundryApi
  });

  return panel;
}

export function getFrameConnDmApplication() {
  return embeddedPanelController;
}

export async function openFrameConnDmApplication() {
  assertRuntime();
  if (!runtime.foundryApi.isPrimaryGM?.()) {
    ui.notifications.warn("Frame Conn // Mission is available to the active GM.");
    return null;
  }

  embeddedPanelVisible = true;
  if (combatTrackerRoot) await renderEmbeddedMissionPanel(combatTrackerRoot);
  return embeddedPanelController;
}

export async function closeFrameConnDmApplication() {
  embeddedPanelVisible = false;
  combatTrackerRoot?.querySelector?.(".lancer-frame-conn-dm-embedded")?.remove();
  return null;
}

export function renderFrameConnDmApplication() {
  return embeddedPanelVisible && combatTrackerRoot
    ? renderEmbeddedMissionPanel(combatTrackerRoot)
    : null;
}

function handleCombatChange() {
  return renderFrameConnDmApplication();
}

async function handleCombatTrackerRender(_application, html) {
  if (!game?.user?.isGM) return false;

  const root = normalizeCombatTrackerRoot(html);
  if (!root?.querySelector) return false;
  combatTrackerRoot = root;

  let button = root.querySelector(".lancer-frame-conn-dm-open-button");

  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "lancer-frame-conn-dm-open-button";
    button.innerHTML = '<i class="fas fa-bullseye"></i> Sitrep';

    const target =
      root.querySelector(".combat-tracker-header") ??
      root.querySelector("header") ??
      root;

    target.prepend(button);
  }

  button.classList.toggle("active", embeddedPanelVisible);
  button.onclick = async event => {
    event.preventDefault();
    embeddedPanelVisible = !embeddedPanelVisible;
    button.classList.toggle("active", embeddedPanelVisible);
    await renderEmbeddedMissionPanel(root);
  };

  await renderEmbeddedMissionPanel(root);
  return true;
}

export const frameConnDmApplicationUiFeature = defineFrameConnFeature({
  id: "ui-dm-application",
  domain: "ui.dm",
  provides: ["ui.dm", "ui.dm.application", "ui.dm.sitrep-presentation"],
  dependsOn: ["dm.sitreps", "foundry.integration"],
  optionalDependsOn: [],
  state: {},
  commands: {
    configureRuntime,
    open: openFrameConnDmApplication,
    close: closeFrameConnDmApplication,
    render: renderFrameConnDmApplication
  },
  queries: { getApplication: getFrameConnDmApplication, runtimeBindings },
  hooks: {
    renderCombatTracker: handleCombatTrackerRender,
    updateCombat: handleCombatChange,
    createCombat: handleCombatChange,
    deleteCombat: handleCombatChange
  },
  lifecycle: {},
  api: {
    configureRuntime,
    open: openFrameConnDmApplication,
    close: closeFrameConnDmApplication,
    render: renderFrameConnDmApplication,
    getApplication: getFrameConnDmApplication,
    runtimeBindings
  },
  metadata: {
    audience: "gm",
    label: "Frame Conn // Mission",
    presentationSurface: "combat-tracker-embedded-panel",
    companionStylesheet: "styles/ui_dm/ui-dm-application.css",
    phase: "sitrep-assimilation-phase-6"
  }
});

/* GM-facing Frame Conn // Mission surface embedded in Foundry's Combat Tracker. */

.lancer-frame-conn-dm-open-button {
  width: 100%;
  min-height: 28px;
  margin: 0 0 .3rem;
  border: 1px solid rgba(91, 224, 217, .38);
  border-radius: 0;
  background: rgba(18, 54, 58, .45);
  color: #d8f7f3;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .04em;
}

.lancer-frame-conn-dm-open-button.active {
  border-color: var(--fc-cyan, #5be0d9);
  color: var(--fc-cyan, #5be0d9);
  box-shadow: inset 0 0 0 1px rgba(91, 224, 217, .18);
}

.lancer-frame-conn-dm-embedded {
  --dm-line: rgba(91, 224, 217, 0.34);
  --dm-accent: var(--fc-cyan, #5be0d9);
  --dm-muted: rgba(216, 247, 243, 0.64);
  flex: 0 0 36%;
  width: 100%;
  min-height: 210px;
  max-height: 38vh;
  margin-top: auto;
  border-top: 1px solid var(--dm-accent);
  background: #071012;
  color: var(--fc-text, #d8f7f3);
  overflow: hidden;
}

.lancer-frame-conn-dm-embedded > .fc-dm-shell {
  height: 100%;
  max-height: 38vh;
}

.fc-dm-shell {
  --dm-line: rgba(91, 224, 217, 0.34);
  --dm-accent: var(--fc-cyan, #5be0d9);
  --dm-muted: rgba(216, 247, 243, 0.64);
  display: flex;
  flex-direction: column;
  gap: .42rem;
  box-sizing: border-box;
  height: 100%;
  padding: .45rem;
  overflow-y: auto;
  background: repeating-linear-gradient(0deg, rgba(255,255,255,.018) 0 1px, transparent 1px 4px);
  font-size: .72rem;
}

.fc-dm-app-header,
.fc-dm-mission-header,
.fc-dm-round-strip {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: .45rem;
  border-bottom: 1px solid var(--dm-line);
  padding-bottom: .28rem;
}

.fc-dm-app-header > div,
.fc-dm-mission-header > div,
.fc-dm-objective-card {
  display: flex;
  flex-direction: column;
  gap: .1rem;
}

.fc-dm-app-header span,
.fc-dm-mission-header span,
.fc-dm-form-grid label > span,
.fc-dm-stat span,
.fc-dm-objective-card > span {
  color: var(--dm-muted);
  font-size: .56rem;
  font-weight: 700;
  letter-spacing: .08em;
}

.fc-dm-mission-header h2 {
  margin: 0;
  color: var(--dm-accent);
  font-size: .9rem;
}

.fc-dm-mission-header > strong {
  color: var(--dm-accent);
  font-size: .62rem;
  letter-spacing: .05em;
}

.fc-dm-objective,
.fc-dm-objective-card,
.fc-dm-result-reason,
.fc-dm-empty,
.fc-dm-error,
.fc-dm-zone-banner,
.fc-dm-control-banner,
.fc-dm-stat,
.fc-dm-zone-card {
  border: 1px solid var(--dm-line);
  background: rgba(0,0,0,.2);
  padding: .36rem;
}

.fc-dm-objective,
.fc-dm-objective-card,
.fc-dm-result-reason,
.fc-dm-error {
  border-left: 3px solid var(--dm-accent);
}

.fc-dm-error { border-left-color: #d56a68; color: #ef9d96; }
.fc-dm-zone-banner, .fc-dm-control-banner { text-align: center; font-weight: 700; letter-spacing: .04em; }

.fc-dm-stat-grid,
.fc-dm-zone-grid,
.fc-dm-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: .28rem;
}

.fc-dm-stat,
.fc-dm-zone-card {
  display: flex;
  flex-direction: column;
  gap: .12rem;
}

.fc-dm-stat strong { font-size: .9rem; }
.fc-dm-stat.allied strong, .fc-dm-zone-card[data-controller="friendly"] span { color: #78dfce; }
.fc-dm-stat.hostile strong, .fc-dm-zone-card[data-controller="hostile"] span { color: #ef8c83; }
.fc-dm-zone-card[data-controller="contested"] span { color: #e0ce7a; }

.fc-dm-setup-form,
.fc-dm-mission-panel {
  display: flex;
  flex-direction: column;
  gap: .35rem;
}

.fc-dm-form-grid label {
  display: flex;
  flex-direction: column;
  gap: .12rem;
  min-width: 0;
}

.fc-dm-form-grid label.wide { grid-column: 1 / -1; }
.fc-dm-form-grid label[hidden] { display: none; }

.fc-dm-form-grid input,
.fc-dm-form-grid textarea,
.fc-dm-form-grid select {
  width: 100%;
  min-width: 0;
  min-height: 24px;
  border: 1px solid var(--dm-line);
  border-radius: 0;
  background: #0a1719;
  color: inherit;
  font-size: .68rem;
}

.fc-dm-form-grid select[multiple] { min-height: 4.5rem; }

.fc-dm-rules {
  display: flex;
  flex-wrap: wrap;
  gap: .25rem .45rem;
  border: 1px solid var(--dm-line);
  padding: .3rem;
}

.fc-dm-command-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: .25rem;
}

.fc-dm-command-row button,
.fc-dm-zone-card button {
  min-height: 25px;
  border: 1px solid var(--dm-line);
  border-radius: 0;
  padding: .22rem .35rem;
  background: rgba(28,85,88,.35);
  color: inherit;
  cursor: pointer;
  font-size: .66rem;
}

.fc-dm-command-row button.primary { border-color: var(--dm-accent); color: var(--dm-accent); }
.fc-dm-command-row button.danger { border-color: #d56a68; color: #ef9d96; }
.fc-dm-command-row button:disabled, .fc-dm-zone-card button:disabled { opacity: .4; cursor: default; }
.fc-dm-validation { min-height: .75rem; color: #ef9d96; font-size: .62rem; }
.fc-dm-empty { margin: auto 0; text-align: center; color: var(--dm-muted); }
